<script setup lang="ts">
import { computed, nextTick, onUnmounted, ref } from 'vue'
import { ArrowLeft, ArrowRight, BookOpen, Check, Download, LoaderCircle, Plus } from '@lucide/vue'
import TerminalShell from '../components/TerminalShell.vue'
import SystemHeader from '../components/SystemHeader.vue'
import HomeAction from '../components/HomeAction.vue'
import OperationStepper from '../components/OperationStepper.vue'
import ReaderSummary from '../components/ReaderSummary.vue'
import ReaderSearch from '../components/ReaderSearch.vue'
import NfcCardAnimation from '../components/NfcCardAnimation.vue'
import ScannerPanel from '../components/ScannerPanel.vue'
import BookRow from '../components/BookRow.vue'
import BookBasket from '../components/BookBasket.vue'
import ActionBar from '../components/ActionBar.vue'
import TouchInput from '../components/TouchInput.vue'
import TouchKeyboard from '../components/TouchKeyboard.vue'
import QuantityControl from '../components/QuantityControl.vue'
import StateMessage from '../components/StateMessage.vue'
import ConnectionStatus from '../components/ConnectionStatus.vue'
import { SEED_READERS, SEED_TITLES, type Reader } from '../domain'

const notice = ref('Выберите компонент, чтобы проверить его поведение.')
const firstReader = SEED_READERS[0]!
const currentReader = ref<Reader>(firstReader)
const inputValue = ref('000124')
const codeInput = ref<InstanceType<typeof TouchInput> | null>(null)
const errorValue = ref('')
const quantity = ref(2)
const selected = ref(true)
const activeStep = ref(1)
const query = ref('Сәрсенова')
const isLoading = ref(false)
const buttonLoading = ref(false)
const keyboardField = ref<'code' | 'error' | 'query' | null>(null)
const keyboardValue = computed({ get: () => keyboardField.value === 'query' ? query.value : keyboardField.value === 'error' ? errorValue.value : inputValue.value, set: value => { if (keyboardField.value === 'query') query.value = value; else if (keyboardField.value === 'error') errorValue.value = value; else inputValue.value = value } })
const nfcState = ref<'idle' | 'reading' | 'success' | 'error'>('idle')
const nfcStates = [{ value: 'idle', label: 'Ожидание' }, { value: 'reading', label: 'Чтение' }, { value: 'success', label: 'Успех' }, { value: 'error', label: 'Ошибка' }] as const
const palette = [{ name: 'Синий EDUS', value: '#046BC8', token: '--edus-blue' }, { name: 'Золотой EDUS', value: '#E39300', token: '--edus-gold' }, { name: 'Тёмный синий', value: '#0B1A4D', token: '--edus-navy' }, { name: 'Белый', value: '#FFFFFF', token: '--surface' }, { name: 'Фон', value: '#F8FBFE', token: '--background' }]
const results = computed(() => query.value.trim() ? SEED_READERS.filter(reader => `${reader.name} ${reader.card}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())) : [])
const books = ref([SEED_TITLES[0]!, SEED_TITLES[1]!])
const server = ref(true)
const internet = ref(true)
let timer: ReturnType<typeof setTimeout> | undefined
function announce(message: string) { notice.value = message }
function chooseReader(reader: Reader) { currentReader.value = reader; announce(`Выбран читатель: ${reader.name}`) }
function removeBook(id: string) { books.value = books.value.filter(book => book.id !== id); announce('Книга убрана только из демонстрационного списка.') }
function restoreBooks() { books.value = [SEED_TITLES[0]!, SEED_TITLES[1]!]; announce('Демонстрационный список восстановлен.') }
function loadingExample() { if (timer) clearTimeout(timer); buttonLoading.value = true; timer = setTimeout(() => { buttonLoading.value = false; announce('Демонстрационная загрузка завершена.') }, 1500) }
function submitInput() { keyboardField.value = null; announce(`Введён код: ${inputValue.value || 'пустое значение'}. Ведущие нули и буквы сохранены.`) }
function openCodeKeyboard() { keyboardField.value = 'code'; nextTick(() => { codeInput.value?.focus(); codeInput.value?.input?.scrollIntoView({ block: 'center', behavior: 'smooth' }) }); announce('Открыта клавиатура для поля «Инвентарный номер».') }
onUnmounted(() => { if (timer) clearTimeout(timer) })
</script>

<template>
  <TerminalShell class="gallery-shell" :class="{ 'with-keyboard': keyboardField }">
    <template #header><SystemHeader time="10:24" @settings="announce('Системные параметры находятся в рабочем терминале. Ниже можно проверить состояния соединения.')" @help="announce('Галерея компонентов: элементы ниже работают с отдельными демонстрационными данными.')" /></template>
    <div class="gallery-page">
      <div class="gallery-top"><a class="btn ghost" href="#/"><ArrowLeft :size="22" :stroke-width="1.8" />В терминал</a><span class="gallery-badge">Дизайн-система · EDUS POS</span></div>
      <div class="gallery-title"><h1>Один язык интерфейса</h1><p>Компоненты, состояния и правила сенсорного терминала библиотеки.</p></div>
      <StateMessage class="gallery-notice" kind="info" title="Интерактивная галерея" :text="notice" />

      <section id="brand" class="gallery-section"><div class="section-title"><span>01</span><div><h2>Бренд и цвет</h2><p>Оригинальный логотип, единый синий для интерфейса и карты.</p></div></div>
        <div class="brand-grid"><div><div class="brand-example"><img src="/assets/edus-logo.png" alt="Оригинальный логотип EDUS" width="280" height="64" /><p>EDUS · Библиотека</p></div><div class="palette"><div v-for="color in palette" :key="color.token" class="palette-item"><div class="swatch" :style="{ background: color.value }" /><strong>{{ color.name }}</strong><code>{{ color.value }}</code><span>{{ color.token }}</span></div></div></div><div class="card-example"><img src="/assets/edus-card-schematic.svg" alt="Контурная схема карты EDUS: тонкие двойные линии и линейная надпись" width="145" /><div><h3>Школьная карта EDUS</h3><p>Инструкционная line-art схема: равномерные двойные контуры, линейный знак и надпись EDUS без заливок.</p><div class="asset-links"><a class="btn secondary" href="/assets/edus-card-schematic.svg" target="_blank" rel="noopener">Открыть SVG<ArrowRight :size="20" :stroke-width="1.8" /></a><a class="btn ghost" href="/assets/edus-card.png" download><Download :size="20" :stroke-width="1.8" />Карта по фото · PNG</a></div></div></div></div>
      </section>

      <section id="typography" class="gallery-section"><div class="section-title"><span>02</span><div><h2>Крупный, читаемый текст</h2><p>Локальный Noto Sans. Русские и казахские символы без внешних запросов.</p></div></div><div class="type-samples"><div><span class="sample-label">Экран · 40 / 49</span><p class="sample-display">Кому выдаём книги?</p></div><div><span class="sample-label">Инструкция · 26 / 35</span><p class="sample-instruction">Поднесите карту к считывателю</p></div><div><span class="sample-label">ФИО и книга · 24 / 32</span><p class="sample-name">Сәрсенова Айша Ерланқызы</p></div><div><span class="sample-label">Основной текст · 20 / 30</span><p class="sample-body">Ә Ғ Қ Ң Ө Ұ Ү Һ І · Қазақ тілі · Білімге қол жеткізу</p></div><div><span class="sample-label">Служебный текст · 16 / 24</span><p class="sample-service">Ведущие нули сохраняются: 000124 · KZ-0007</p></div></div></section>

      <section id="actions" class="gallery-section"><div class="section-title"><span>03</span><div><h2>Три основные операции</h2><p>Вся поверхность карточки — область нажатия.</p></div></div><div class="home-examples"><HomeAction title="Выдать книги" description="Выберите читателя и отсканируйте книги" icon="issue" accent @click="announce('Выбрана выдача книг. В рабочем интерфейсе открывается ожидание карты.')" /><HomeAction title="Принять книги" description="Выберите читателя и отметьте его книги" icon="return" @click="announce('Выбран приём книг. Сначала выберите читателя по карте.')" /><HomeAction title="Добавить книги" description="Зарегистрируйте поступление в фонд" icon="add" @click="announce('Выбрана регистрация поступления в фонд.')" /></div></section>

      <section id="controls" class="gallery-section"><div class="section-title"><span>04</span><div><h2>Действия и ввод</h2><p>Основное действие — 72 px. Дополнительные touch-зоны — от 56 px.</p></div></div><div class="button-examples"><div><span class="sample-label">Обычная</span><button class="btn primary" type="button" @click="announce('Нажата основная кнопка.')">Выдать 2 книги<ArrowRight :size="24" :stroke-width="1.8" /></button></div><div><span class="sample-label">Нажатая</span><button class="btn primary pressed-example" type="button" @click="announce('Пример нажатого состояния: действие принято.')">Подтвердить</button></div><div><span class="sample-label">Выбрана</span><button class="btn selected" type="button" :aria-pressed="selected" :class="{ selected }" @click="selected = !selected; announce(selected ? 'Параметр выбран.' : 'Выбор снят.')"><Check v-if="selected" :size="22" :stroke-width="1.8" />По экземплярам</button></div><div><span class="sample-label">Недоступна</span><button class="btn primary" type="button" disabled>Продолжить</button></div><div><span class="sample-label">Загрузка</span><button class="btn primary" type="button" :disabled="buttonLoading" :aria-busy="buttonLoading" @click="loadingExample"><LoaderCircle v-if="buttonLoading" class="spinner" :size="24" :stroke-width="1.8" /><span>{{ buttonLoading ? 'Сохраняем…' : 'Проверить загрузку' }}</span></button></div><div><span class="sample-label">Вторичная</span><button class="btn secondary" type="button" @click="announce('Вторичное действие: возврат на предыдущий шаг.')">Назад</button></div></div><div class="field-examples"><TouchInput ref="codeInput" v-model="inputValue" label="Инвентарный номер" placeholder="Например, 000124 или KZ-0007" @keyboard="keyboardField = 'code'" @enter="submitInput" /><TouchInput v-model="errorValue" label="Обязательное поле" placeholder="Введите название книги" :error="errorValue.trim() ? '' : 'Укажите название книги'" @keyboard="keyboardField = 'error'" @enter="announce(errorValue.trim() ? 'Название принято.' : 'Поле необходимо заполнить.')" /><TouchInput model-value="Поле недоступно во время отправки" label="Недоступное поле" disabled /><div class="quantity-example"><span class="sample-label">Количество · от 1 до 12</span><QuantityControl v-model="quantity" :max="12" /><span>{{ quantity }} шт. будет добавлено в список</span></div></div></section>

      <section id="reader" class="gallery-section"><div class="section-title"><span>05</span><div><h2>Читатель и поиск</h2><p>ФИО, класс и книги на руках. Без фотографий и аватаров.</p></div></div><ReaderSummary :name="currentReader.name" :group="currentReader.group" :count="3" @change="currentReader = currentReader.id === firstReader.id ? SEED_READERS[1]! : firstReader; announce('Читатель изменён в примере.')" /><div class="two-columns reader-examples"><ReaderSearch v-model="query" :results="results" :searched="!!query.trim()" :loading="isLoading" @keyboard="keyboardField = 'query'" @select="chooseReader" /><div class="example-notes"><h3>Состояния поиска</h3><p>Введите «Сәрсенова», чтобы увидеть несколько результатов. «Нет такого» покажет пустое состояние.</p><button class="btn secondary" :aria-pressed="isLoading" type="button" @click="isLoading = !isLoading">{{ isLoading ? 'Завершить загрузку' : 'Показать загрузку' }}</button><button class="btn ghost" type="button" @click="query = 'Нет такого'; isLoading = false">Показать пустой результат</button><p class="small">Данные в галерее изолированы от рабочей демонстрации.</p></div></div></section>

      <section id="nfc" class="gallery-section"><div class="section-title"><span>06</span><div><h2>Карта читателя</h2><p>Спокойное ожидание, чтение и подтверждённый результат в одном устойчивом блоке.</p></div></div><div class="nfc-demo"><NfcCardAnimation :state="nfcState" /><div class="nfc-controls"><span class="sample-label">Демонстрация состояний карты</span><h3>{{ nfcStates.find(item => item.value === nfcState)?.label }}</h3><div class="state-switch"><button v-for="state in nfcStates" :key="state.value" class="btn" :class="{ selected: nfcState === state.value }" :aria-pressed="nfcState === state.value" type="button" @click="nfcState = state.value">{{ state.label }}</button></div><p>Фронтальная схема карты сохраняет положение во всех состояниях. Линия чтения движется внутри контура; при уменьшенном движении она неподвижна. Галочка появляется только после подтверждения.</p></div></div></section>

      <section id="books" class="gallery-section"><div class="section-title"><span>07</span><div><h2>Сканирование и список книг</h2><p>Список прокручивается внутри; действие удаления убирает книгу только из корзины.</p></div></div><div class="two-columns books-examples"><ScannerPanel compact @manual="openCodeKeyboard" /><BookBasket title="К выдаче" :count="books.length"><template #action><button class="btn ghost basket-reset" type="button" @click="restoreBooks">Восстановить</button></template><BookRow v-for="(book, index) in books" :key="book.id" :title="book.name" :author="book.author" :code="index === 0 ? '000124' : 'KZ-0007'" mode="COPY" @remove="removeBook(book.id)" /><template #empty><div><p>В списке пока нет книг</p><button class="btn secondary" type="button" @click="restoreBooks"><Plus :size="22" :stroke-width="1.8" />Восстановить пример</button></div></template></BookBasket></div><div class="book-selection-example"><BookRow title="Қазақстан тарихы. 8-сынып" author="З. Е. Қабылдинов, А. Т. Қайыпбаева" mode="LEGACY_TITLE" :quantity="quantity" :selected="selected" :removable="false" @select="selected = !selected" /></div></section>

      <section id="states" class="gallery-section"><div class="section-title"><span>08</span><div><h2>Состояния и обратная связь</h2><p>Цвет поддерживает текст. Ошибка и отсутствие сети не теряют текущий список.</p></div></div><div class="states-grid"><StateMessage kind="success" title="Книги выданы" text="Операция подтверждена. Можно перейти к следующему читателю." /><StateMessage kind="error" title="Эта книга уже выдана" text="Проверьте номер экземпляра. Текущий список сохранён." /><StateMessage kind="warning" title="Результат уточняется" text="Операция отправлена. Проверьте результат перед повторной выдачей." /><StateMessage kind="info" title="Найдено издание по ISBN" text="Укажите индивидуальный номер или выберите учёт старого фонда количеством." /></div></section>

      <section id="shell" class="gallery-section"><div class="section-title"><span>09</span><div><h2>Постоянная оболочка</h2><p>Этапы и подтверждение сохраняют своё место в рабочем сценарии.</p></div></div><div class="stepper-example"><OperationStepper :steps="['Читатель', 'Книги', 'Подтверждение']" :active="activeStep" /><button class="btn secondary" type="button" @click="activeStep = (activeStep + 1) % 3">Следующий этап</button></div><div class="bar-example"><ActionBar><button class="btn secondary" type="button" @click="announce('Возврат на предыдущий шаг.')"><ArrowLeft :size="22" :stroke-width="1.8" />Назад</button><template #right><span class="action-count-example">{{ books.length }} книги в списке</span><button class="btn primary" type="button" :disabled="books.length === 0" @click="announce(`Подтверждён пример выдачи: ${books.length} книги. Рабочие данные не изменены.`)"><BookOpen :size="24" :stroke-width="1.8" />Выдать {{ books.length }} книги</button></template></ActionBar></div><div class="connection-controls"><button class="btn" :class="{ selected: server }" type="button" :aria-pressed="server" @click="server = !server">Сервер: {{ server ? 'доступен' : 'нет связи' }}</button><button class="btn" :class="{ selected: internet }" type="button" :aria-pressed="internet" @click="internet = !internet">Интернет: {{ internet ? 'доступен' : 'нет связи' }}</button><span>Состояния ниже моделируются отдельно</span></div><ConnectionStatus :server="server" :internet="internet" /></section>
      <div class="gallery-end"><a class="btn secondary" href="#/"><ArrowLeft :size="22" :stroke-width="1.8" />Вернуться в библиотеку</a><p>EDUS POS · Компоненты построены на единых токенах и локальных ассетах.</p></div>
    </div>
    <TouchKeyboard v-if="keyboardField" v-model="keyboardValue" :label="keyboardField === 'query' ? 'Найти читателя' : keyboardField === 'error' ? 'Название книги' : 'Инвентарный номер'" @close="keyboardField = null" @enter="announce('Ввод с экранной клавиатуры завершён.')" />
  </TerminalShell>
</template>

<style scoped>
