 line-height: 1.55; margin-top: 20px; max-width: 640px; }.books-examples { gap: 32px; grid-template-columns: .7fr 1.3fr; }.books-examples :deep(.book-basket) { max-height: 380px; }.basket-reset { margin-left: auto; font-size: 16px; padding: 10px 12px; }.book-selection-example { border: 1px solid var(--line); border-radius: 14px; overflow: hidden; margin-top: 24px; }.states-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }.stepper-example { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-bottom: 24px; }.bar-example { border: 1px solid var(--line); border-radius: 16px; overflow: hidden; }.bar-example :deep(.action-bar) { border-top: 0; padding: 20px 24px; }.action-count-example { font-size: 18px; color: var(--muted); }.connection-controls { display: flex; align-items: center; flex-wrap: wrap; gap: 16px; margin: 32px 0 20px; }.connection-controls > span { color: var(--muted); font-size: 17px; }.gallery-end { display: flex; justify-content: space-between; align-items: center; gap: 32px; padding: 36px 0 0; }.gallery-end p { font-size: 16px; color: var(--muted); }.with-keyboard .gallery-page { padding-bottom: 340px; }.spinner { animation: spin 1s linear infinite; }@keyframes spin { to { transform: rotate(360deg); } }
